-- --------------------------------------------------------
DROP TABLE IF EXISTS `dpcs`;
CREATE TABLE `dpcs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `head_name` varchar(255) DEFAULT NULL,
  `address` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `order` bigint(20) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table `dpcs`
INSERT INTO `dpcs` (`id`, `name`, `slug`, `description`, `head_name`, `address`, `order`, `created_at`, `updated_at`) VALUES
(1, 'DPC PKS Indralaya', 'dpc-pks-indralaya', 'DPC PKS Indralaya merupakan sentra koordinasi kepengurusan tingkat kecamatan di pusat ibukota Kabupaten Ogan Ilir. Berfokus pada pelayanan advokasi warga, pengawalan kebijakan publik, program Jumat Berkah rutin, serta pembinaan generasi muda dan keluarga tangguh.', 'Ustadz H. Ahmad Ridwan, S.Pd.I', 'Jl. Lintas Timur KM 35, Indralaya Mulya, Kec. Indralaya, Kab. Ogan Ilir', 1, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(2, 'DPC PKS Indralaya Utara', 'dpc-pks-indralaya-utara', 'DPC PKS Indralaya Utara aktif menggerakkan pemberdayaan ekonomi masyarakat pedesaan, sektor pertanian pangan, serta penyelenggaraan layanan pemeriksaan kesehatan gratis dan tanggap darurat warga.', 'Ust. Syarif Hidayatullah', 'Kel. Timbangan / Lorok, Kec. Indralaya Utara, Kab. Ogan Ilir', 2, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(3, 'DPC PKS Indralaya Selatan', 'dpc-pks-indralaya-selatan', 'DPC PKS Indralaya Selatan giat menyelenggarakan pembinaan keagamaan, olahraga pemuda, pendampingan petani lokal, dan program santunan yatim dhuafa di wilayah Indralaya Selatan.', 'Ust. M. Zulkifli, S.E', 'Desa Meranjat, Kec. Indralaya Selatan, Kab. Ogan Ilir', 3, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(4, 'DPC PKS Tanjung Raja', 'dpc-pks-tanjung-raja', 'DPC PKS Tanjung Raja menjadi salah satu simpul khidmat masyarakat terbesar dengan fokus pada advokasi pedagang pasar tradisional, pembinaan UMKM kuliner dan kerajinan, serta layanan mobil siaga warga.', 'Ust. Drs. Rusli Nawawi', 'Jl. Pasar Baru Tanjung Raja, Kec. Tanjung Raja, Kab. Ogan Ilir', 4, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(5, 'DPC PKS Tanjung Batu', 'dpc-pks-tanjung-batu', 'DPC PKS Tanjung Batu aktif mendampingi para pengrajin pandai besi dan perak tradisional khas Tanjung Batu, mengokohkan konsolidasi ranting (DPRa), serta menyelenggarakan pendidikan baca Al-Qur''an untuk anak-anak.', 'Ust. Baihaqi, S.Kom', 'Kel. Tanjung Batu, Kec. Tanjung Batu, Kab. Ogan Ilir', 5, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(6, 'DPC PKS Payaraman', 'dpc-pks-payaraman', 'DPC PKS Payaraman berkomitmen melayani masyarakat pekebun karet dan sawit rakyat, memperjuangkan stabilisasi harga hasil bumi, dan mendampingi kelompok majelis taklim ibu-ibu.', 'Ust. Hasan Basri', 'Jl. Raya Payaraman, Kec. Payaraman, Kab. Ogan Ilir', 6, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(7, 'DPC PKS Pemulutan', 'dpc-pks-pemulutan', 'DPC PKS Pemulutan berfokus melayani kawasan perairan dan rawa lebak dengan program advokasi nelayan tangkap, pemenuhan air bersih pedesaan, serta penanganan berkala luapan pasang surut.', 'Ust. Fauzi Usman, S.Pd', 'Desa Ibul Besar / Pemulutan Ilir, Kec. Pemulutan, Kab. Ogan Ilir', 7, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(8, 'DPC PKS Pemulutan Barat', 'dpc-pks-pemulutan-barat', 'DPC PKS Pemulutan Barat menggiatkan program pembinaan ketahanan pangan keluarga, pelatihan wirausaha rumahan perempuan PKS, serta penyaluran bantuan sosial kemanusiaan.', 'Ust. Muhammad Sholeh', 'Desa Talang Pangeran, Kec. Pemulutan Barat, Kab. Ogan Ilir', 8, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(9, 'DPC PKS Pemulutan Selatan', 'dpc-pks-pemulutan-selatan', 'DPC PKS Pemulutan Selatan hadir sebagai mitra warga desa dalam mengawal bantuan bibit pertanian, kegiatan kepemudaan karang taruna, dan santunan pendidikan siswa kurang mampu.', 'Ust. M. Ridho Ansori', 'Desa Sungai Keli, Kec. Pemulutan Selatan, Kab. Ogan Ilir', 9, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(10, 'DPC PKS Rantau Alai', 'dpc-pks-rantau-alai', 'DPC PKS Rantau Alai konsisten melayani wilayah pedalaman dengan mengawal ketersediaan sarana jalan tani, lumbung pangan dhuafa, dan fasilitasi rujukan kesehatan darurat.', 'Ust. Syafei Harun', 'Desa Rantau Alai, Kec. Rantau Alai, Kab. Ogan Ilir', 10, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(11, 'DPC PKS Rantau Panjang', 'dpc-pks-rantau-panjang', 'DPC PKS Rantau Panjang memperkuat silaturahim lintas tokoh agama dan adat, mengawal penanggulangan bencana banjir musiman, serta melayani pelatihan keahlian pemuda desa.', 'Ust. K.H. Mansyur Syah', 'Desa Rantau Panjang Ilir, Kec. Rantau Panjang, Kab. Ogan Ilir', 11, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(12, 'DPC PKS Sungai Pinang', 'dpc-pks-sungai-pinang', 'DPC PKS Sungai Pinang membina para pengrajin anyaman purun dan rotan khas Ogan Ilir, serta rutin mengadakan cek kesehatan dan pengajian akbar warga di pelosok desa.', 'Ust. Abdullah Faqih', 'Desa Sungai Pinang Jaya, Kec. Sungai Pinang, Kab. Ogan Ilir', 12, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(13, 'DPC PKS Muara Kuang', 'dpc-pks-muara-kuang', 'DPC PKS Muara Kuang menjadi garda perkhidmatan di wilayah selatan Ogan Ilir yang mengawal aspirasi petani karet, perbaikan infrastruktur pedesaan, dan advokasi beasiswa santri.', 'Ust. Hendra Gunawan, S.H', 'Kel. Muara Kuang, Kec. Muara Kuang, Kab. Ogan Ilir', 13, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(14, 'DPC PKS Rambang Kuang', 'dpc-pks-rambang-kuang', 'DPC PKS Rambang Kuang berfokus pada pembinaan masyarakat berbasis perkebunan, advokasi hak pekerja perkebunan, serta penyediaan layanan sosial khidmat bencana alam.', 'Ust. H. Subki Mansyur', 'Desa Tambang Rambang, Kec. Rambang Kuang, Kab. Ogan Ilir', 14, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(15, 'DPC PKS Lubuk Keliat', 'dpc-pks-lubuk-keliat', 'DPC PKS Lubuk Keliat giat membangun sinergi bersama kelompok tani tebu dan karet, mendorong regenerasi kepemimpinan pemuda desa, dan memperkuat basis ketahanan keluarga.', 'Ust. M. Darwin, S.Ag', 'Desa Betung, Kec. Lubuk Keliat, Kab. Ogan Ilir', 15, '2026-09-05 10:59:37', '2026-09-05 10:59:37'),
(16, 'DPC PKS Kandis', 'dpc-pks-kandis', 'DPC PKS Kandis mengabdi untuk masyarakat di ujung selatan Ogan Ilir dengan menyediakan bimbingan belajar anak, pendampingan petani kebun, dan kegiatan silaturahim akbar tahunan.', 'Ust. Zulkarnain, S.Pd', 'Desa Kandis I, Kec. Kandis, Kab. Ogan Ilir', 16, '2026-09-05 10:59:37', '2026-09-05 10:59:37');

