-- Dumping data for table `testimonials`
INSERT INTO `testimonials` (`id`, `name`, `profession`, `content`, `photo`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Jumadi', 'Petani Karet', '“Sebagai petani, saya merasa PKS Ogan Ilir dekat dengan masyarakat kecil. Mereka sering datang ke desa, mendengarkan keluhan kami tentang harga karet dan kebutuhan pupuk. Harapan saya, dengan kepengurusan baru, PKS bisa semakin kuat memperjuangkan nasib petani di parlemen.”
', '/uploads/2023/08/user-2.webp', 'publish', '2026-09-05 09:50:10', '2026-09-05 09:50:10'),
(2, 'Siti Rahmawati', 'Guru SD', '“Sejak dulu saya melihat PKS Ogan Ilir aktif turun ke masyarakat, khususnya dalam bidang pendidikan dan sosial. Bagi saya, partai ini bukan hanya bicara soal politik, tapi juga hadir membantu kebutuhan warga. Musda VI kemarin menambah keyakinan saya bahwa PKS punya komitmen besar untuk masa depan Ogan Ilir.”
', '/uploads/2023/08/user-2.webp', 'publish', '2026-09-05 09:50:10', '2026-09-05 09:50:10'),
(3, 'Lina Marlina', 'Pelaku UMKM', '“Sebagai pelaku usaha kecil, saya merasa PKS selalu terbuka menerima aspirasi kami. Beberapa kali saya melihat kegiatan PKS yang membantu UMKM untuk berkembang, seperti bazar dan pelatihan usaha. Saya berharap di periode kepengurusan baru ini, PKS bisa lebih banyak mendukung pelaku UMKM agar ekonomi masyarakat makin maju.”
', '/uploads/2023/08/user-2.webp', 'publish', '2026-09-05 09:50:10', '2026-09-05 09:50:10'),
(4, 'Nur Aisyah', 'Pedagang', '“Anak muda sekarang butuh partai yang memberi ruang dan semangat untuk berkreasi. Saya melihat PKS Ogan Ilir memberi peluang besar kepada kader mudanya untuk berperan aktif. Regenerasi kepemimpinan yang terjadi di Musda VI membuktikan kalau PKS serius melibatkan generasi muda.”
', '/uploads/2023/08/user-2.webp', 'publish', '2026-09-05 09:50:10', '2026-09-05 09:50:10');

